function BulkFleetModal({companyId,kind,ids,close,done}){const[action,setAction]=useState('STATUS'),[status,setStatus]=useState('AVAILABLE'),[error,setError]=useState(''),[busy,setBusy]=useState(false);const options=kind==='driver'?['AVAILABLE','OFF_DUTY','INACTIVE']:['AVAILABLE','MAINTENANCE','INACTIVE'];const submit=async ev=>{ev.preventDefault();setBusy(true);setError('');try{const d=await api(logPath(companyId,'/fleet/bulk'),{method:'POST',body:JSON.stringify({kind,ids,action,status})});if(d.skipped)window.alert(`${d.updated} updated; ${d.skipped} skipped because of active work or lifecycle rules.`);done()}catch(x){setError(x.message)}finally{setBusy(false)}};return <Modal title={`Bulk ${kind} action`} close={close}><form className="form" onSubmit={submit}>{error&&<div className="alert error">{error}</div>}<div className="alert info">{ids.length} record(s) selected. Active trips are protected from unsafe archive/off-duty/maintenance changes.</div><label>Action<select value={action} onChange={ev=>setAction(ev.target.value)}><option value="STATUS">Change status</option><option value="ARCHIVE">Archive</option></select></label>{action==='STATUS'&&<label>New status<select value={status} onChange={ev=>setStatus(ev.target.value)}>{options.map(x=><option key={x}>{x}</option>)}</select></label>}<div className="modal-actions"><button type="button" className="btn secondary" onClick={close}>Cancel</button><button className="btn primary" disabled={busy}>{busy?'Applying…':'Apply to selected'}</button></div></form></Modal>}
