function FleetHistory({companyId,row}){const[d,setD]=useState({items:[],total:0}),[e,setE]=useState('');useEffect(()=>{let live=true;api(logPath(companyId,`/fleet/${row.kind}/${row._id}/history?pageSize=20`)).then(x=>live&&setD(x)).catch(x=>live&&setE(x.message));return()=>{live=false}},[companyId,row.kind,row._id]);return <div className="detail-section"><h3>Dispatch history</h3>{e&&<div className="alert error">{e}</div>}<div className="linked-record-list">{(d.items||[]).map(x=><div className="beneficiary-service-row" key={x._id}><div><b>{x.shipmentNo} · {x.agencyId?.name||'Internal transfer'}</b><small>{x.workPackageId?.code||'No Work Package'} · {x.dispatchedAt?new Date(x.dispatchedAt).toLocaleString():'Not dispatched'}{x.expectedDeliveryAt?` · ETA ${new Date(x.expectedDeliveryAt).toLocaleString()}`:''}</small></div><Status value={x.issueFlag?'ATTENTION':x.status}/></div>)}{!d.items?.length&&<div className="empty">No dispatch history for this record yet.</div>}</div>{d.total>20&&<small className="live-note">Showing latest 20 of {d.total} dispatches.</small>}</div>}

