 <div className="command-bar"><div className="search-box"><Search size={17}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search shipment number"/></div><FilterButton count={filterCount} onClick={()=>setFiltersOpen(true)}/><span className="result-count">{fmt(meta.total)} shipments</span></div>
